// Preparar prompt para generar 3 variaciones de guion
const item = $input.first();
const fields = item.json.fields || item.json;

const ideaId = item.json.id || 'ID_DESCONOCIDO';
const titulo = fields.titulo || 'Sin titulo';
const hook = fields.hook || 'Sin hook';
const concepto = fields.concepto || 'Sin concepto';
const formato = fields.formato || 'Video corto';
const pilar = fields.pilar || 'Herramientas';
const anguloEmocional = fields.angulo_emocional || '';
const palabrasClave = fields.palabras_clave || '';
const duracionEstimada = fields.duracion_estimada || '60-90 segundos';
const notas = fields.notas_produccion || '';

const prompt = `Eres el guionista principal de NOA, una aplicacion para padres de adolescentes con Altas Capacidades Cognitivas (AACC).

Tu tarea es crear 3 variaciones de guion completo para el siguiente contenido aprobado:

---
TITULO: ${titulo}
HOOK INICIAL: ${hook}
CONCEPTO: ${concepto}
FORMATO: ${formato}
PILAR EMOCIONAL: ${pilar}
ANGULO EMOCIONAL: ${anguloEmocional}
PALABRAS CLAVE: ${palabrasClave}
DURACION ESTIMADA: ${duracionEstimada}
NOTAS ADICIONALES: ${notas}
---

PAUTAS DE ESCRITURA NOA:
- Tono: Cercano, empatico, como un amigo que tambien es experto
- Evitar: Tecnicismos sin explicar, tono condescendiente, soluciones simplistas
- Incluir: Validacion emocional, datos concretos cuando aplique, llamada a la accion clara
- Estructura para video: Hook (3 seg) → Promesa (5 seg) → Desarrollo (40-60 seg) → CTA (5-10 seg)
- Usar 'tu' para dirigirse al padre/madre
- Los adolescentes con AACC no son 'superdotados' en el sentido elitista; son ninos con necesidades especificas

VARIACION 1 - EMOCIONAL: Enfocada en la conexion emocional y validacion del padre/madre
VARIACION 2 - PRACTICA: Enfocada en herramientas y pasos accionables
VARIACION 3 - NARRATIVA: Usa una historia o caso real (anonimizado) para ilustrar el concepto

Responde UNICAMENTE con un JSON valido con esta estructura:
{
  "idea_id": "${ideaId}",
  "titulo_original": "${titulo}",
  "guiones": [
    {
      "variacion": "EMOCIONAL",
      "titulo_guion": "Titulo especifico para esta variacion",
      "hook": "Texto exacto del hook (primeros 3-5 segundos)",
      "cuerpo": "Texto completo del guion con indicaciones de pausa y enfasis en MAYUSCULAS",
      "cta": "Llamada a la accion final",
      "palabras_totales": 150,
      "duracion_estimada_seg": 60,
      "notas_produccion": "Indicaciones para grabacion o diseno",
      "hashtags_sugeridos": ["#hashtag1", "#hashtag2"]
    },
    {
      "variacion": "PRACTICA",
      "titulo_guion": "Titulo especifico para esta variacion",
      "hook": "Texto exacto del hook",
      "cuerpo": "Texto completo del guion",
      "cta": "Llamada a la accion final",
      "palabras_totales": 150,
      "duracion_estimada_seg": 60,
      "notas_produccion": "Indicaciones para grabacion o diseno",
      "hashtags_sugeridos": ["#hashtag1", "#hashtag2"]
    },
    {
      "variacion": "NARRATIVA",
      "titulo_guion": "Titulo especifico para esta variacion",
      "hook": "Texto exacto del hook",
      "cuerpo": "Texto completo del guion",
      "cta": "Llamada a la accion final",
      "palabras_totales": 150,
      "duracion_estimada_seg": 60,
      "notas_produccion": "Indicaciones para grabacion o diseno",
      "hashtags_sugeridos": ["#hashtag1", "#hashtag2"]
    }
  ]
}`;

return [{
  json: {
    prompt: prompt,
    idea_id: ideaId,
    titulo: titulo,
    formato: formato,
    pilar: pilar,
    campos_originales: fields
  }
}];

