// Parsear las 3 variaciones de guion de la respuesta de Claude
const claudeResponse = $input.first().json;
const contexto = $('Code: Construir Prompt Guion').first().json;

if (!claudeResponse.content || !claudeResponse.content[0] || !claudeResponse.content[0].text) {
  throw new Error('Respuesta de Claude vacia o invalida para guiones');
}

const rawText = claudeResponse.content[0].text;

// Extraer bloque JSON
let jsonString = rawText;
const jsonMatch = rawText.match(/\{[\s\S]*\}/);
if (jsonMatch) {
  jsonString = jsonMatch[0];
}

let parsed;
try {
  parsed = JSON.parse(jsonString);
} catch (e) {
  throw new Error(`Error parseando JSON de guiones: ${e.message}\nPrimeros 500 chars: ${rawText.substring(0, 500)}`);
}

if (!parsed.guiones || !Array.isArray(parsed.guiones)) {
  throw new Error('La respuesta no contiene el array de guiones');
}

const fechaHoy = new Date().toISOString().split('T')[0];

// Formatear cada guion para Airtable
const guionesFormateados = parsed.guiones.map((guion, index) => ({
  json: {
    fields: {
      idea_id: parsed.idea_id || contexto.idea_id,
      titulo_original_idea: parsed.titulo_original || contexto.titulo,
      variacion: guion.variacion || `VARIACION_${index + 1}`,
      titulo_guion: guion.titulo_guion || `Guion ${index + 1}`,
      hook: guion.hook || '',
      cuerpo: guion.cuerpo || '',
      cta: guion.cta || '',
      palabras_totales: guion.palabras_totales || 0,
      duracion_estimada_seg: guion.duracion_estimada_seg || 60,
      notas_produccion: guion.notas_produccion || '',
      hashtags_sugeridos: Array.isArray(guion.hashtags_sugeridos)
        ? guion.hashtags_sugeridos.join(' ')
        : guion.hashtags_sugeridos || '',
      estado: 'REVISION',
      fecha_creacion: fechaHoy,
      modelo_ia: 'claude-opus-4-5',
      formato: contexto.formato,
      pilar: contexto.pilar
    },
    _idea_id: contexto.idea_id
  }
}));

return guionesFormateados;

// Agregar todos los guiones creados para construir el resumen
const guionesCreados = $input.all();

// Obtener ID de la idea original del primer item
const ideaId = guionesCreados[0]?.json?._idea_id || guionesCreados[0]?.json?.fields?.idea_id || 'ID_DESCONOCIDO';

return [{
  json: {
    total_guiones: guionesCreados.length,
    idea_id: ideaId,
    guiones_ids: guionesCreados.map(g => g.json.id).filter(Boolean),
    guiones_titulos: guionesCreados.map(g => {
      const f = g.json.fields || g.json;
      return `${f.variacion}: ${f.titulo_guion || 'Sin titulo'}`;
    }),
    timestamp: new Date().toISOString()
  }
}];

